SELECT p.id, p.symbol, p.opened_at, p.closed_at, p.close_reason, p.realized_pnl FROM paper_position p WHERE (p.opened_at < '2026-10-09 10:29:00' AND (p.closed_at IS NULL OR p.closed_at > '2026-10-09 10:23:00')) OR (p.opened_at < '2026-10-10 00:19:00' AND (p.closed_at IS NULL OR p.closed_at > '2026-10-10 00:11:00')) OR (p.opened_at < '2026-10-10 01:56:00' AND (p.closed_at IS NULL OR p.closed_at > '2026-10-10 01:48:00')) OR (p.opened_at < '2026-10-10 18:03:00' AND (p.closed_at IS NULL OR p.closed_at > '2026-10-10 17:55:00')) OR (p.opened_at < '2026-10-11 02:44:00' AND (p.closed_at IS NULL OR p.closed_at > '2026-10-11 02:37:00')) ORDER BY p.opened_at LIMIT 50;